(window.webpackJsonp=window.webpackJsonp||[]).push([[54],{419:function(t,v,_){"use strict";_.r(v);var a=_(11),r=Object(a.a)({},(function(){var t=this,v=t._self._c;return v("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[v("h2",{attrs:{id:"大冰主持人简介"}},[v("a",{staticClass:"header-anchor",attrs:{href:"#大冰主持人简介"}},[t._v("#")]),t._v(" 大冰主持人简介")]),t._v(" "),v("p",[v("code",[t._v("大冰")]),t._v("（原名冰田），中国著名主持人、作家、音乐人。1981年生于哈尔滨，内蒙古赤峰人。曾主持《开心麻花》，出版《摆渡人》，创作发行歌曲等。")]),t._v(" "),v("h2",{attrs:{id:"感悟"}},[v("a",{staticClass:"header-anchor",attrs:{href:"#感悟"}},[t._v("#")]),t._v(" 感悟")]),t._v(" "),v("p",[t._v("大冰老师很神奇，听他说话，让我踏实且发自内心的平和。一种从内而外的人生厚度，通过屏幕传递给观众。允许他人是他人，允许自己是自己。这是我很早就知道的一句话，且发自内心的认同并实践。但是从大冰老师嘴里再次听到，还是觉得深厚温暖，有着厚重的能量扑面而来。")]),t._v(" "),v("p",[t._v("这个世界很大有很多要探索，这是创造力的来源。在三五个方向前进，七八个方向好奇，核心是对生活、对自我、对他人、对社会的关系、态度和行动。引发我思考的是，有些时候浅谈兴趣或许是害怕实践。怕麻烦的本质是无法坦然面对自己。")]),t._v(" "),v("p",[t._v("还有大冰老师的疙瘩汤理论。儿童时期，人是清水，慢慢变成柠檬水，气泡水···和疙瘩汤。让我想到害人之心不可有，防人之心不可无这句话。随着人长大，经历多了，有些道理和人生经验让人懂得进退有度，半满即智慧。")]),t._v(" "),v("p",[t._v("最新看到大冰老师的切片，感悟是人要习得工具性技能，即生存根本，来维持生活。那么这个习得的时间最好是在学习能力强的黄金时期。当然学无止境，人可以一辈子在学习的路上，玩和学，看见和发现，人生就是一场生命体在时间维度上的体验。")]),t._v(" "),v("p",[t._v("另一个感悟是大冰老师说的人的社会属性和自然属性，大冰老师说社会属性为先，但我先达成了自然属性。某种程度上社会属性（保障自己存活）发展缓慢，这个属性需要锻炼且重要。")]),t._v(" "),v("p",[t._v("最近（04月01日）看大冰老师的切片，冰哥说未来ai等情感咨询，会以一种更科学陪伴时间更长的方式帮助大家认识到自己。但ai有很多局限，比如ai的分析只局限于认知当下的科学镜印，还存在一些当个体不能客观描述自身情况，情感操控自身，或自我主体性边界性不强，不能用元认知客观观察自身时，会出现出差较大的思维误区。所以现实个体的感悟和支持还是很有必要的。")]),t._v(" "),v("br"),t._v(" "),v("hr"),t._v(" "),v("div",{staticClass:"center-container"},[v("p",[t._v("📢 "),v("code",[t._v("版权声明")]),t._v("：本文为原创文章，著作权归 "),v("code",[t._v("【赵敏】")]),t._v(" 所有。"),v("code",[t._v("禁止转载，侵权必究")]),t._v("。")])]),v("br")])}),[],!1,null,null,null);v.default=r.exports}}]);